// Reference data shipped with the client: every AIRAC cycle in src/data/ref/cycles (generated by
// tools/build_ref.ts; do not edit the JSON), the one in effect now and the ones loaded ahead of their date. A flight
// is planned with the cycle in effect on its date (flightAiracDay), so a flight after a cycle's effective date sees
// that cycle's AIP while it is planned before; pages with no flight use today's. The same records are in the ref_*
// tables for the API (GET /api/ref/…), chosen by the same rule (api/_lib/airac.ts).
import { aerodromeIndex } from '../../shared/aerodrome';
import {
  airacDay,
  cycleOn,
  flightAiracDay,
  type RefAdAirspace,
  type RefAerodrome,
  type RefAirac,
  type RefAirspace,
  type RefArea,
  type RefBundle,
  type RefCycle,
  type RefFir,
  type RefFis,
  type RefNavaid,
  type RefRunway,
  type RefSunTable,
  type RefVfrPoint,
  type RefVfrRoute,
} from '../../shared/ref';
import { type AipLinks, aipLinksOn } from '../aipLinks';
import { CYCLES } from './cycles';
// Not per cycle: tools/build_fir.ts (ENR 2.1 + OpenStreetMap land borders), client only.
import firJson from './fir.json';

/** The LGGG FIR boundary and the ATHINAI / MAKEDONIA line. */
export const FIR = firJson as unknown as RefFir;

/** One cycle's reference data with its lookups. */
export interface RefView {
  airac: RefAirac;
  ref: RefBundle;
  /** AIP GEN 2.7 sunset tables keyed by ICAO. */
  sun: Record<string, RefSunTable>;
  aip: AipLinks;
  /** Aerodrome by id or ICAO. */
  aerodrome: (idOrIcao: string | null | undefined) => RefAerodrome | undefined;
  vfrPoint: (id: string | null | undefined) => RefVfrPoint | undefined;
  /** Runway directions of an aerodrome. */
  runwaysOf: (aerodromeId: string) => RefRunway[];
  /** The aerodrome a typed text names: exact id/ICAO, else a unique name match. */
  resolveAerodrome: (text: string) => RefAerodrome | undefined;
  /** Suggestions for a query: ICAO prefix matches first, then name matches. */
  searchAerodromes: (q: string, limit?: number) => RefAerodrome[];
}

const views = new Map<string, RefView>();

function viewOf(c: RefCycle): RefView {
  const known = views.get(c.airac.id);
  if (known) return known;
  const index = aerodromeIndex(c.aerodromes);
  const vfrById = new Map(c.vfrPoints.map((p) => [p.id, p]));
  const runways = new Map<string, RefRunway[]>();
  for (const r of c.runways) runways.set(r.aerodromeId, [...(runways.get(r.aerodromeId) ?? []), r]);
  const v: RefView = {
    airac: c.airac,
    ref: {
      airac: c.airac,
      aerodromes: c.aerodromes,
      runways: c.runways,
      airspaces: c.airspaces,
      fis: c.fis,
      vfrPoints: c.vfrPoints,
      vfrRoutes: c.vfrRoutes,
      atcUnits: c.atcUnits,
      adAirspaces: c.adAirspaces,
      areas: c.areas,
      fir: FIR,
      navaids: c.navaids,
    },
    sun: c.sun,
    aip: aipLinksOn(c.airac.effective),
    aerodrome: index.find,
    vfrPoint: (id) => (id ? vfrById.get(id) : undefined),
    runwaysOf: (id) => runways.get(id) ?? [],
    resolveAerodrome: index.resolve,
    searchAerodromes: (q, limit = 8) => {
      const u = q.trim().toUpperCase();
      if (!u) return [];
      const score = (a: RefAerodrome) => {
        const code = (a.icao || a.id).toUpperCase();
        if (code === u) return 0;
        if (code.startsWith(u)) return 1;
        if (a.name.toUpperCase().split(/[\s/,-]+/).some((w) => w.startsWith(u))) return 2;
        if (a.name.toUpperCase().includes(u)) return 3;
        return 9;
      };
      return c.aerodromes
        .map((a) => [score(a), a] as const)
        .filter(([s]) => s < 9)
        .sort(
          (x, y) => x[0] - y[0] || (x[1].icao ? 0 : 1) - (y[1].icao ? 0 : 1) || x[1].name.localeCompare(y[1].name),
        )
        .slice(0, limit)
        .map(([, a]) => a);
    },
  };
  views.set(c.airac.id, v);
  return v;
}

/** The reference data in effect on a day ('YYYY-MM-DD'). */
export const refOn = (day: string): RefView => viewOf(cycleOn(CYCLES, day));
/** The reference data a flight is planned with: the cycle in effect on its date (today when it has none). */
export const refOfFlight = (date: string | null | undefined): RefView => refOn(flightAiracDay(date));
/** Today's reference data (by the clock, so a page open across a cycle's date follows it). */
export const refToday = (): RefView => refOn(airacDay());
/** The cycles shipped that are in effect today or later, oldest first. */
export const airacsFromToday = (): RefAirac[] => {
  const now = refToday().airac;
  return CYCLES.map((c) => c.airac)
    .filter((a) => a.effective >= now.effective)
    .sort((a, b) => a.effective.localeCompare(b.effective));
};

// The cycle in effect when this module loaded, for tests and fixtures (app code takes a RefView).
export const CYCLE = cycleOn(CYCLES, airacDay());
export const AIRAC = CYCLE.airac;
export const AERODROMES: RefAerodrome[] = CYCLE.aerodromes;
export const RUNWAYS: RefRunway[] = CYCLE.runways;
export const AIRSPACES: RefAirspace[] = CYCLE.airspaces;
export const FIS: RefFis = CYCLE.fis;
export const VFR_POINTS: RefVfrPoint[] = CYCLE.vfrPoints;
export const VFR_ROUTES: RefVfrRoute[] = CYCLE.vfrRoutes;
/** Aerodrome CTRs and ATZs (AD 2.17 / AD 1.6.N.17). */
export const AD_AIRSPACES: RefAdAirspace[] = CYCLE.adAirspaces;
/** ENR 5.1 / 5.2 / 5.3 areas (prohibited, restricted, danger, military, other activities). */
export const AREAS: RefArea[] = CYCLE.areas;
/** Radio navigation aids (VOR, VOR/DME, NDB, locators). */
export const NAVAIDS: RefNavaid[] = CYCLE.navaids;
/** AIP GEN 2.7 sunset tables keyed by ICAO. */
export const SUN_TABLES: Record<string, RefSunTable> = CYCLE.sun;

const loaded = viewOf(CYCLE);
export const REF: RefBundle = loaded.ref;
export const aerodrome = loaded.aerodrome;
export const vfrPoint = loaded.vfrPoint;
export const runwaysOf = loaded.runwaysOf;
export const resolveAerodrome = loaded.resolveAerodrome;
export const searchAerodromes = loaded.searchAerodromes;
